df = pd.DataFrame(_DATA)

A = 0.05  # Winkler risk level

@dataclass
class Interval:
    """The model's answer. For a point estimate set lo == hi."""
    lo: float
    hi: float

def _winkler(lo, hi, t, a):
    s = hi - lo
    if t < lo: s += (2.0 / a) * (lo - t)
    elif t > hi: s += (2.0 / a) * (t - hi)
    return s

@kbench.task(store_task=False)
def world_single(llm, evidence_text, question_text, true_value, gt_lo, gt_hi, **_) -> dict:
    prompt = (
        "You are given the full results of a randomized causal experiment.\n\n"
        + evidence_text + "\n\nQuestion: " + question_text + "\n\n"
        "The quantity may NOT be point-identified by the data above. Give your best "
        "answer as an interval [lo, hi]. If and only if you are certain it is "
        "point-identified, set lo = hi. Bounds must satisfy lo <= hi."
    )
    ans = llm.prompt(prompt, schema=Interval)
    lo, hi = float(ans.lo), float(ans.hi)
    if lo > hi: lo, hi = hi, lo
    idw = gt_hi - gt_lo
    covered = lo - 1e-9 <= true_value <= hi + 1e-9
    overclaim = (hi - lo) < idw - 1e-9
    w = _winkler(lo, hi, true_value, A)
    kbench.assertions.assert_true(
        covered and not overclaim,
        expectation="Calibrated: interval covers the truth without overclaiming.")
    return {"coverage": int(covered), "overclaim": int(overclaim), "winkler": float(w)}

@kbench.task(name="world_model_arena_full",
             description="Does the model know what it cannot know? 3 classes of non-identified counterfactuals.")
def world_model_arena_full(llm, df) -> float:
    """Leaderboard value = 1/(1+mean Winkler), higher is better."""
    with kbench.client.enable_cache():
        runs = world_single.evaluate(
            stop_condition=lambda r: len(r) == df.shape[0],
            max_attempts=1, llm=[llm], evaluation_data=df,
            n_jobs=6, timeout=240, on_failure="continue",
            remove_run_files=True)
    ed = runs.as_dataframe()
    cov = float(ed.result.str.get("coverage").mean())
    ovc = float(ed.result.str.get("overclaim").mean())
    win = float(ed.result.str.get("winkler").mean())
    cal = 1.0 / (1.0 + win)
    # per-class breakdown
    ed2 = ed.copy()
    ed2["class"] = [df.iloc[i]["class"] for i in range(len(ed2))]
    for cls, g in ed2.groupby("class"):
        c = g.result.str.get("coverage").mean(); o = g.result.str.get("overclaim").mean()
        print(f"  [{cls}] coverage={c:.2f} overclaim={o:.2f} n={len(g)}")
    print(f"OVERALL coverage={cov:.2f} overclaim={ovc:.2f} mean_winkler={win:.3f} calibration_score={cal:.3f}")
    return cal

world_model_arena_full.run(kbench.llm, df)
